using System;using System.IO;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json;
public static class DestinationPrepare {public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("B5 Edit scene required");var repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var dir=Path.Combine(Path.GetTempPath(),"AfterSeconds_DestinationColors_"+DateTime.Now.ToString("yyyyMMdd_HHmmss"));Directory.CreateDirectory(dir);File.Copy(Path.GetFullPath(Path.Combine(Application.dataPath,"..",s.path)),Path.Combine(dir,"disk_before.unity"));bool dirty=s.isDirty;if(!EditorSceneManager.SaveScene(s,Path.Combine(dir,"editing_before.unity"),true))throw new Exception("Backup failed");if(dirty&&!EditorSceneManager.SaveScene(s))throw new Exception("Save failed");var result=new{backup=dir,preservedUnsavedChanges=dirty,scene=s.path};Directory.CreateDirectory(repo+"/Docs/검수/2026-11-08_B5_DestinationColors");File.WriteAllText(repo+"/Docs/검수/2026-11-08_B5_DestinationColors/backup.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}}
